data.transform:
(
  $errorObjectTemplate := {
    "inputReceived": $,
    "acceptableExamples": [
      {
        "inventory": {
          "quantity": 1.2,
          "shippable": false,
          "number": "S000000001",
          "handlingUnitId": "123",
          "inventoryStatusId": "OK",
          "lastTransactionTypeId": "123",
          "locationId": "123"
        }
      },
      {
        "inventory": [
          {
            "quantity": 1.2,
            "shippable": false,
            "number": "S000000001",
            "handlingUnitId": "123",
            "inventoryStatusId": "OK",
            "lastTransactionTypeId": "123",
            "locationId": "123"
          },
          {
            "quantity": 1.2,
            "shippable": false,
            "handlingUnitId": "123",
            "inventoryStatusId": "OK",
            "lastTransactionTypeId": "123",
            "locationId": "123"
          }
        ]
      }
    ]
  };

  $not($exists(inventory)) ?
    $throw(
      "CreateInventory Flow input must be an object with an \"inventory\" property",
      $errorObjectTemplate
    );
  
  $isArray(inventory) and $isEmpty(inventory) ?
    $throw(
      "CreateInventory Flow \"inventory\" input cannot be an empty array. No inventory data provided to create.",
      $errorObjectTemplate
    );
    
  /* Always return inventory as an array for simplified validation in the next node */
  [inventory];
)

data.variablesTransform:
{
  "payload": [$.{
    "create": $~>|$|(
      $shelfLifeDays := product.shelfLifeDays;
      {
      "quantity":{ "value": quantity, "unitId": product.defaultQuantityUnitId},
      "grossWeight": {"value": quantity*product.weight.value, "unitId": product.weight.unitId},
      "netWeight": {"value": quantity*product.weight.value, "unitId": product.weight.unitId},
      "expiresAt": product.shelfLifeDays? $moment().startOf("day").add($shelfLifeDays, "day")
      }), ["product"] |
  }]
}

data.query:
query Product($where: ProductWhereInput, $orderBy: [ProductOrderByInput!], $first: Int, $after: String) {
  product(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        shelfLifeDays
        weight {
          value
          unitId
        }
        defaultQuantityUnitId
      }
    }
  }
}

